import React, { createContext, useContext } from 'react';
const ConversationStoreContext = createContext(null);
export const ConversationStoreProvider = ({ store, children }) => (React.createElement(ConversationStoreContext.Provider, { value: store }, children));
export const useConversationStore = () => {
    const store = useContext(ConversationStoreContext);
    if (!store) {
        throw new Error('useConversationStore must be used within a ConversationStoreProvider');
    }
    return store;
};
